185			page, err = s.AuditPage(page.Checkpoint, page.Next, 1, "", "")
186			if err != nil {
187				t.Fatal(err)
188			}
189			queried = append(queried, page.Records...)
190		}
191		if !reflect.DeepEqual(queried, recs) {
192			t.Fatal("paged query bytes differ from the export bytes")
193		}
194	
195		// Offline review recomputes from the raw request and recorded version.
196		review, err := RecheckDecisionOffline("acme", recs, cp, 2)
197		if err != nil {
198			t.Fatalf("offline review: %v", err)
199		}
200		if !review.Consistent || !reflect.DeepEqual(review.Original, d) ||
201			!reflect.DeepEqual(review.Recomputed, d) {
202			t.Fatalf("offline review = %+v, want consistent with %+v", review, d)
203		}
204		if !strings.Contains(review.Recomputed.Matched[0], invalidByte) {
205			t.Fatal("offline review normalized the matched policy id")
206		}
207	
208		// An organization whose name itself carries invalid bytes: genesis
209		// checkpoint, isolation and offline review all still work.
210		weirdOrg := "组" + invalidByte + "织"
211		if _, err := s.Publish(weirdOrg, 0, []Policy{submitted}); err != nil {
212			t.Fatalf("publish into invalid-UTF-8 org: %v", err)
213		}
214		wreq := req
215		wreq.SubjectOrg = weirdOrg
216		wreq.ResourceOrg = weirdOrg
217		if d := s.Decide(weirdOrg, wreq); !d.Allowed {
218			t.Fatalf("decision inside invalid-UTF-8 org = %+v", d)
219		}
220		wrecs, wcp, err := s.AuditExport(weirdOrg, 0)
221		if err != nil {
222			t.Fatal(err)
223		}
224		if err := VerifyAudit(weirdOrg, wrecs, wcp); err != nil {
225			t.Fatalf("invalid-UTF-8 org chain: %v", err)
226		}
227		if wr, err := RecheckDecisionOffline(weirdOrg, wrecs, wcp, 2); err != nil || !wr.Consistent {
228			t.Fatalf("invalid-UTF-8 org offline review = %+v, %v", wr, err)
229		}
230		// The sequence-0 root checkpoint is the genesis for that org too.
231		empty, emptyCP, err := s.AuditExport(weirdOrg+"-none", 0)
232		if err != nil {
233			t.Fatal(err)
234		}
235		if err := VerifyAudit(weirdOrg+"-none", empty, emptyCP); err != nil {
236			t.Fatalf("genesis checkpoint: %v", err)
237		}
238	}
