354	// TestTamperedInvalidBytesRejectedEverywhere replaces the lone 0xFF in
355	// every protected field with either 0xFE (the same display after JSON
356	// replacement) or a genuine U+FFFD. VerifyAudit must fail with
357	// ErrInvalidRange and offline review must refuse before returning any
358	// conclusion, including when the damage is after the target decision.
359	func TestTamperedInvalidBytesRejectedEverywhere(t *testing.T) {
360		org, good, cp := buildInvalidByteChain(t)
361	
362		// Document the root cause: JSON renders both raw bytes identically.
363		j1, _ := json.Marshal("身" + invalidByte + "份")
364		j2, _ := json.Marshal("身" + anotherInvalidByte + "份")
365		if !bytes.Equal(j1, j2) {
366			t.Fatalf("test premise broken: JSON differs: %s vs %s", j1, j2)
367		}
368	
369		mutators := []struct {
370			name string
371			fn   func([]AuditRecord, string)
372		}{
373			{"header org", func(r []AuditRecord, repl string) {
374				r[0].Org = strings.Replace(r[0].Org, invalidByte, repl, 1)
375			}},
376			{"record kind", func(r []AuditRecord, repl string) {
377				r[1].Kind += repl
378			}},
379			{"policy id", func(r []AuditRecord, repl string) {
380				p := &r[0].Change.Policies[0]
381				p.ID = strings.Replace(p.ID, invalidByte, repl, 1)
382			}},
383			{"policy subject", func(r []AuditRecord, repl string) {
384				p := &r[0].Change.Policies[0]
385				p.Subject = strings.Replace(p.Subject, invalidByte, repl, 1)
386			}},
387			{"policy action", func(r []AuditRecord, repl string) {
388				p := &r[0].Change.Policies[0]
389				p.Action = strings.Replace(p.Action, invalidByte, repl, 1)
390			}},
391			{"policy scope", func(r []AuditRecord, repl string) {
392				p := &r[0].Change.Policies[0]
393				p.Scope = strings.Replace(p.Scope, invalidByte, repl, 1)
394			}},
395			{"policy effect", func(r []AuditRecord, repl string) {
396				p := &r[0].Change.Policies[0]
397				p.Effect = Effect(string(p.Effect) + repl)
398			}},
399			{"second policy in list", func(r []AuditRecord, repl string) {
400				p := &r[0].Change.Policies[1]
401				p.ID = strings.Replace(p.ID, invalidByte, repl, 1)
402			}},
403			{"subject org", func(r []AuditRecord, repl string) {
404				r[1].Decision.Request.SubjectOrg = strings.Replace(r[1].Decision.Request.SubjectOrg, invalidByte, repl, 1)
405			}},
406			{"resource org", func(r []AuditRecord, repl string) {
407				r[1].Decision.Request.ResourceOrg = strings.Replace(r[1].Decision.Request.ResourceOrg, invalidByte, repl, 1)
408			}},
409			{"subject id between chinese", func(r []AuditRecord, repl string) {
410				id := &r[1].Decision.Request.Subject.ID
411				*id = strings.Replace(*id, invalidByte, repl, 1)
412			}},
413			{"subject kind", func(r []AuditRecord, repl string) {
414				r[1].Decision.Request.Subject.Kind = strings.Replace(r[1].Decision.Request.Subject.Kind, invalidByte, repl, 1)
415			}},
416			{"first role in list", func(r []AuditRecord, repl string) {
417				roles := r[1].Decision.Request.Subject.Roles
418				roles[0] = strings.Replace(roles[0], invalidByte, repl, 1)
419			}},
420			{"second role in list", func(r []AuditRecord, repl string) {
421				r[1].Decision.Request.Subject.Roles[1] += repl
422			}},
423			{"resource id", func(r []AuditRecord, repl string) {
424				r[1].Decision.Request.Resource.ID = strings.Replace(r[1].Decision.Request.Resource.ID, invalidByte, repl, 1)
425			}},
426			{"resource scope", func(r []AuditRecord, repl string) {
427				r[1].Decision.Request.Resource.Scope = strings.Replace(r[1].Decision.Request.Resource.Scope, invalidByte, repl, 1)
428			}},
429			{"request action", func(r []AuditRecord, repl string) {
430				r[1].Decision.Request.Action = strings.Replace(r[1].Decision.Request.Action, invalidByte, repl, 1)
431			}},
432			{"decision reason", func(r []AuditRecord, repl string) {
433				r[1].Decision.Decision.Reason = strings.Replace(r[1].Decision.Decision.Reason, invalidByte, repl, 1)
434			}},
435			{"first matched policy", func(r []AuditRecord, repl string) {
436				m := r[1].Decision.Decision.Matched
437				m[0] = strings.Replace(m[0], invalidByte, repl, 1)
438			}},
439			{"second matched policy", func(r []AuditRecord, repl string) {
440				m := r[1].Decision.Decision.Matched
441				m[1] = strings.Replace(m[1], invalidByte, repl, 1)
442			}},
443			{"record after target", func(r []AuditRecord, repl string) {
444				id := &r[2].Decision.Request.Subject.ID
445				*id = strings.Replace(*id, invalidByte, repl, 1)
446			}},
447		}
448	
449		for _, repl := range []string{anotherInvalidByte, replacementRune} {
450			for _, m := range mutators {
451				recs := cloneExportedRecords(good)
452				m.fn(recs, repl)
453				name := m.name + "/repl=" + replacementLabel(repl)
454				if err := VerifyAudit(org, recs, cp); !errors.Is(err, ErrInvalidRange) {
455					t.Fatalf("%s: VerifyAudit err = %v, want ErrInvalidRange", name, err)
456				}
457				// Offline review must reject first: never a successful or
458				// "consistent" conclusion over tampered material.
459				if got, err := RecheckDecisionOffline(org, recs, cp, 2); !errors.Is(err, ErrInvalidRange) {
460					t.Fatalf("%s: RecheckDecisionOffline err = %v, review = %+v, want ErrInvalidRange", name, err, got)
461				}
462			}
463		}
464	}
